from pathlib import Path
import subprocess,json,collections
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'instagram'
def put(name,text):
 p=OUT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def progress(text):
 with (OUT/'PROGRESS.md').open('a',encoding='utf-8') as f:f.write('\n- '+text+'\n')
rows=[]
for folder in sorted(list(ROOT.glob('Dia-*'))+list((ROOT/'canal').glob('*'))):
 if not folder.is_dir():continue
 videos=sorted((folder/'entregables').glob('*.mp4'))
 for p in videos:
  q=subprocess.run(['ffprobe','-v','error','-show_entries','format=duration:stream=codec_type,width,height','-of','json',str(p)],capture_output=True,text=True)
  data=json.loads(q.stdout) if q.returncode==0 else {}
  v=next((s for s in data.get('streams',[]) if s.get('codec_type')=='video'),{})
  duration=data.get('format',{}).get('duration','no verificado')
  n=folder.name; status='por decidir';reason='Revisión audiovisual completa y publicación TikTok no confirmadas.';source='marcador.md: sin publicación; estado.md/relevo.md: sin aprobación de este archivo.'
  if n=='Dia-01':reason='Elegir v4/v5; portada histórica roja, rehacer con Eléctrico; confirmar TikTok.';source='estado.md Día 1: editado, publicación pendiente; relevo 7-oct: elegir v4/v5.'
  elif n=='Dia-02':
   reason='v10 es referencia vigente; afirmaciones CRM sin E2E y promesa DIAN para mañana: revisar/corregir el video, no solo el caption. Confirmar versión publicada.'
   source='estado.md: publicado (versión anterior, red no identificada); marcador sin versión; relevo 9-oct: v10.'
   if 'v10' not in p.stem:status='NO republicar';reason='Versión anterior sustituida por v10; no duplicar. Mantiene afirmaciones CRM/DIAN pendientes de revisión.'
  elif n=='Dia-03':reason='Falta portada; caption.md solo dice Pendiente; revisión de corte sin aprobar. DIAN sigue pendiente.';source='estado.md Día 3 y relevo 10-oct: editado, usuario revisa.'
  elif n=='Dia-04':
   source='estado.md Día 4 y relevo 11/13-oct: entrenos y v1; EDL final con placa Día 5.'
   if 'v1_' in p.name:status='NO republicar';reason='Día 4 v1: motivacional, sin música; exclusión expresa de Monoga.'
   elif 'entreno' in p.name:status='NO republicar';reason='Entrenamiento de estilo, no episodio final; tema motivacional.'
   else:reason='Tema motivacional también en EDL final y numeración Día 4/Día 5 contradictoria; no consta aprobación para publicar.'
  elif n=='Dia-07':
   source='estado.md Día 7; relevo 13/14-oct: revisar en celular y elegir portada.'
   reason='Afirmaciones de agentes de ventas no están en hechos.md; falta caption y aprobación audiovisual/portada.' if 'Dia7' in p.name else 'NotebookLM/servicios documentados no figuran en hechos.md; revisar privacidad, licencias y afirmaciones antes de decidir.'
  elif n=='2026-10-17_17h':reason='NOTAS.md declara afirmaciones del flujo sin hechos.md; elegir un corte, revisar audio, tokens/toques, privacidad y permiso del diagrama ajeno.';source='relevo 17-oct cortes 2/3 y NOTAS.md: revisión pendiente.'
  elif n in ['2026-10-17_19h','2026-10-17_19h-b']:
   status='NO republicar';reason='Audio malo (exclusión expresa del pedido y contexto HANDOFF); promesas de tres sistemas D1-D3 no existentes/verificados.';source='relevo 20-oct aún pedía revisión; HANDOFF vigente: D1-D3 inactivos, sin E2E; pedido 23-oct excluye ambas ediciones.'
  elif n=='2026-10-21_11h':status='NO republicar';reason='Rechazado por Monoga; método monoga-videos descartado. No publicar promesas D1-D3.';source='HANDOFF: intento previo rechazado, 21-oct.'
  reels=[str(x.relative_to(ROOT)).replace('\\','/') for x in videos if 'reels' in x.stem.lower()]
  covers=[str(x.relative_to(ROOT)).replace('\\','/') for x in (folder/'entregables').glob('*') if 'portada' in x.stem.lower() and x.suffix.lower() in ['.png','.jpg','.jpeg']]
  rows.append(dict(path=p.relative_to(ROOT).as_posix(),duration=duration,width=v.get('width'),height=v.get('height'),reels=reels,caption=(folder/'caption.md').exists(),covers=covers,status=status,reason=reason,source=source,tiktok='no confirmado'))
put('borradores/medidas.json',json.dumps(rows,ensure_ascii=False,indent=2))
c=collections.Counter(x['status'] for x in rows)
text='# Inventario local · 2026-10-23\n\nRutas relativas a `Maquina de redes/`. Medidas obtenidas con ffprobe; evidencia bruta en `borradores/medidas.json`. Conteo por archivo, NO por episodio: listos 0; dudosos '+str(c['por decidir'])+'; excluidos '+str(c['NO republicar'])+'; total '+str(len(rows))+'.\n\nListo exigiría aprobación de contenido/audio, portada vigente y confirmación de publicación TikTok. No se ha visto ni oído íntegramente cada MP4: ningún archivo se declara listo. Las variantes TikTok/Reels no son episodios diferentes.\n\n| Video | Segundos | Resolución | Variante Reels en carpeta | caption.md | Portada en entregables | TikTok | Decisión y motivo | Evidencia de estado |\n|---|---:|---|---|---|---|---|---|---|\n'
for x in rows:
 text+='| `'+x['path']+'` | '+str(round(float(x['duration']),3) if x['duration']!='no verificado' else x['duration'])+' | '+str(x['width'])+'×'+str(x['height'])+' | '+('; '.join('`'+p.split('/')[-1]+'`' for p in x['reels']) or 'no')+' | '+('sí (no implica completo)' if x['caption'] else 'no')+' | '+('; '.join('`'+p.split('/')[-1]+'`' for p in x['covers']) or 'no')+' | no confirmado | **'+x['status']+'**: '+x['reason']+' | '+x['source']+' |\n'
text+='\n## Sin video (no se suman al conteo de archivos)\n- `canal/2026-10-21_21h/entregables/`: solo descripcion.txt; **NO republicar**, pausado sin MP4 según HANDOFF y comprobación local. Además, frase de agente sin verificar.\n- `Dia-08/entregables/`: sin MP4; no hay material para republicar. D1-D3 no están confirmados en hechos.md.\n\n## Contrastes\n- marcador.md no registra publicaciones. estado.md dice Día 2 publicado (versión anterior), sin especificar TikTok: no confirma plataforma ni versión. Día 1 sigue ❓ en hechos.md.\n- hechos.md confirma CRM local históricamente, no ventas autónomas ni nube; DIAN, WhatsApp y cotizaciones son próximamente. HANDOFF no permite convertir prototipos D1-D3 en servicios reales. Un caption no corrige una promesa falsa del audio.\n- La marca pastel/dorado aparece en estados históricos de video; para este kit prevalecen el pedido y las reglas de Instagram: Eléctrico, sin rojo. No se alteraron originales.\n'
put('inventario.md',text);progress('Paso 1 terminado: inventario y ffprobe; '+str(len(rows))+' MP4, 0 listos, '+str(c['por decidir'])+' dudosos, '+str(c['NO republicar'])+' excluidos. Canal 21h sin MP4 se registra aparte.')
items=[('1','Dia-01/entregables/Dia1_v5_Reels.mp4','DÍA 1 / 42 DÍAS','Día 1 de 42.\nLoovo ya existe. Ahora quiero mostrar cómo lo construimos.\n\nLo que no cabía en el video: este es el inicio del archivo de la serie, no una actualización de hoy.\n📍 Plazo de la serie: 42 días.\n🎯 Meta: mostrar las decisiones de Loovo.\n👀 Regla: no presentar pruebas como resultados.\nMarcador: Día 1 de 42; sin métricas confirmadas.\n¿Qué parte de construir una empresa te gustaría ver?\n#42DiasLoovo #Loovo'),('2','Dia-02/entregables/final_reels_v10.mp4','DÍA 2 / EDITAR CON IA','Día 2 de 42.\nUn editor con IA ya editó el primer video.\n\nLo que no cabía en el video: el CRM es una adaptación de un proyecto open source, no lo construí desde cero. Lo del agente del CRM lo estamos probando; la DIAN queda para próximamente, sin fecha prometida.\n📍 Plazo: 42 días.\n🎯 Meta: mostrar cómo armamos Loovo.\n👀 Regla: una prueba no es un servicio listo.\nMarcador: Día 2 de 42; sin métricas confirmadas.\n¿Qué revisarías antes de usar IA en tu negocio?\n#42DiasLoovo #Loovo'),('3','Dia-03/entregables/Dia3_final_reels.mp4','DÍA 3 / PASO A PASO','Día 3 de 42.\nAsí que seguimos mostrando Loovo paso a paso.\n\nLo que no cabía en el video: integrar la DIAN sigue para próximamente. Este video pertenece al archivo de la serie; no anuncia una integración lista.\n📍 Plazo: 42 días.\n🎯 Meta: mostrar la construcción de Loovo.\n👀 Regla: contar también lo que falta.\nMarcador: Día 3 de 42; sin métricas confirmadas.\n¿Qué parte quieres que expliquemos con más detalle?\n#42DiasLoovo #Loovo')]
queue='# Cola propuesta · NO autorizada para publicar\n\n**Cola liberada: vacía.** Orden cronológico condicional de candidatos: Día 1 → Día 2 → Día 3. No incluir Día 4, Día 7 ni canal mientras tengan bloqueos. v5 es solo propuesta; Monoga debe escoger v4/v5. No publicar ambas.\n\nRitmo propuesto: un video cada dos días, solo después de liberar cada pieza; si falta revisión, se aplaza. Es una decisión editorial para revisar con calma, no una afirmación sobre el algoritmo. Mantener la fecha original en el contexto; no decir hoy/mañana como si fuera grabado ahora.\n'
for day,path,cover,caption in items:
 assert len(caption)<900 and caption.count('#')<=5 and '#42DiasLoovo' in caption
 queue+=f'\n## Día {day}\n- Video existente: `{path}` (ruta relativa a Maquina de redes).\n- Estado: **por decidir / no publicado por este trabajo**; bloqueos en inventario.md.\n- Portada propuesta: «{cover}», carbón + azul + un foco lima, Space Grotesk 700 e Instrument Serif cursiva. Sin persona generada. **Pendiente de producir y aprobar**; no usar portada antigua roja.\n- Caption propuesto ({len(caption)} caracteres):\n\n```text\n{caption}\n```\n- Línea de mañana omitida: no hay siguiente grabación confirmada por Monoga. No se inventaron métricas ni servicios lanzados.\n'
queue+='\n## Datos de Instagram · consulta 2026-10-23\n| Dato | Estado |\n|---|---|\n| Duración máxima de Reels | no verificado |\n| Proporción de cuadrícula del perfil | no verificado |\n| Tamaño oficial portada de destacada | no verificado |\n| Límite caption | no verificado |\n| Límite título destacada | no verificado |\n\nSe intentó ayuda oficial: https://help.instagram.com/1038071743007909 y https://help.instagram.com/813938898787367 — ambas devolvieron «Page appears to be JavaScript-rendered (content loads dynamically)». Búsqueda arrojó terceros, descartados como verificación oficial. Los títulos ≤15 y captions <900 son restricciones del pedido, no límites oficiales certificados. Lienzos 1080×1920 y posts 1080×1350 son decisiones de producción, no recomendaciones oficiales verificadas. Recorte real de perfil/círculo pendiente de comprobar en celular.\n'
put('cola.md',queue);progress('Paso 2 terminado: cola condicional Día 1/2/3, captions validados <900 caracteres y ≤5 hashtags. Cinco límites de Instagram no verificados; ayuda oficial inaccesible sin login.')
highlights=[('La serie','Presentar el archivo de 42 días.',['Texto: «42 días para mostrar Loovo».','Imagen de marca: «Loovo existe».','Texto: «Día 1: 7 de octubre. Día 42: 17 de noviembre».']),('Loovo','Explicar qué es Loovo sin vender humo.',['Texto: «Loovo es una agencia de inteligencia artificial».','Imagen de marca: «Paso a paso».','Texto: «Adapté un CRM open source; no lo construí desde cero».']),('El editor','Mostrar el uso confirmado de IA en edición.',['Texto: «Un editor con IA editó el Día 1».','Imagen de marca: «De grabación a video».','Texto: «7 min 37 s de grabación quedaron en 38 s».']),('CRM local','Delimitar lo que existe, sin prometer producción.',['Texto: «Adapté un CRM open source».','Texto: «Etapas en español, pesos COP y campos de consentimiento».','Texto: «Verificado en el computador el 7 de octubre; eso no es una prueba de producción actual».']),('Sin humo','Enseñar a distinguir reglas de IA.',['Texto: «Capturar lead extrae nombre, empresa, dolor y presupuesto».','Imagen de marca: «Motor de reglas».','Texto: «Crea el contacto, el trato y la tarea. No es IA».']),('Modo demo','Explicar una práctica sin mostrar datos ajenos.',['Texto: «El CRM tiene un modo demo con datos ficticios».','Imagen de marca: «Datos ficticios».','Texto: «El modo demo se abre con start.ps1 -Demo; CRM.bat abre la base real».'])]
plan='# Destacadas propuestas · seis borradores\n\nPrimero Monoga debe publicar las stories; después las agrupa en destacadas. No hay stories ni destacadas publicadas por esta fase. Títulos ≤15 por pedido (límite oficial no verificado). Todas las piezas siguientes son texto/imagen de marca, no capturas de un sistema actual ni testimonios. No se usarán videos dudosos para saltarse su revisión.\n'
for title,purpose,stories in highlights:
 assert len(title)<=15
